import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import org.junit.jupiter.api.Test;

class OrderServiceExpiryTest {

    // 2026-11-10 12:00 Warsaw (CET, UTC+1)
    private static final Clock NOW = Clock.fixed(Instant.parse("2026-11-10T11:00:00Z"), ZoneId.of("UTC"));

    private final OrderRepository repo = new OrderRepository();
    private final OrderService service = new OrderService(repo, NOW);

    private String placed(String placedAt) {
        Order order = new Order("o-" + placedAt, "c-1", Money.pln(100), Instant.parse(placedAt));
        repo.save(order);
        return order.id();
    }

    @Test
    void cancelsPlacedOrdersOlderThan30WarsawDays() {
        String old = placed("2026-10-01T10:00:00Z");   // 40 days ago
        String edge = placed("2026-10-11T10:00:00Z");  // exactly 30 days ago: not expired
        String recent = placed("2026-11-01T10:00:00Z");

        assertEquals(1, service.expireStale());

        assertEquals("CANCELLED", repo.get(old).status());
        assertEquals("PLACED", repo.get(edge).status());
        assertEquals("PLACED", repo.get(recent).status());
    }

    @Test
    void leavesOrdersInOtherStatusesAlone() {
        String confirmed = placed("2026-09-01T10:00:00Z");
        repo.get(confirmed).changeStatus("CONFIRMED");

        assertEquals(0, service.expireStale());
        assertEquals("CONFIRMED", repo.get(confirmed).status());
    }

    @Test
    void usesTheWarsawCalendarDay() {
        // 2026-10-11 23:30 Warsaw (CEST, UTC+2) is 21:30 UTC, still 2026-10-11 in Warsaw.
        // Cutoff is 2026-10-11 (today 2026-11-10 minus 30 days), so this order is not yet expired.
        String lateEvening = placed("2026-10-11T21:30:00Z");
        // 2026-10-10 00:30 Warsaw is 2026-10-09 22:30 UTC: its Warsaw date is 2026-10-10, expired.
        String justBefore = placed("2026-10-09T22:30:00Z");

        assertEquals(1, service.expireStale());
        assertEquals("PLACED", repo.get(lateEvening).status());
        assertEquals("CANCELLED", repo.get(justBefore).status());
    }

    @Test
    void secondRunCancelsNothingMore() {
        placed("2026-09-01T10:00:00Z");
        assertEquals(1, service.expireStale());
        assertEquals(0, service.expireStale());
    }
}
}
